def largestPrimeFactor (N : Nat) : Nat := N.primeFactors.sup id

def check (n k : Nat) : Bool :=
  decide (2 ≤ n ∧ n ≤ 40 ∧ 1 ≤ k ∧ k ≤ n ∧ largestPrimeFactor (n.choose k) ≥ min (n - k + 1) k)

def P (n k : Nat) : Nat := (Nat.choose n k).primeFactors.sup id

def check_instance : Bool :=
  decide ((P 24 12 : Nat)^100 >= (12 : Nat)^119)

